package protodesign

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/pluginpb"
)

// PluginHeaders open the files the two plugins write. The output sweep
// recognises pb code by them under the pb directory.
var PluginHeaders = []string{
	"// Code generated by protoc-gen-go. DO NOT EDIT.",
	"// Code generated by protoc-gen-go-grpc. DO NOT EDIT.",
}

// Plugin is one protobuf plugin: the name go.mod pins it under, and the
// command the manifest may name instead.
type Plugin struct {
	Name    string
	Command string
}

// plugins lists the two plugins in the order they run.
func (o Options) plugins() []Plugin {
	return []Plugin{
		{Name: "protoc-gen-go", Command: o.PluginGo},
		{Name: "protoc-gen-go-grpc", Command: o.PluginGoGrpc},
	}
}

// RunPlugins writes the pb code of set: protoc-gen-go, then
// protoc-gen-go-grpc, each handed the request protoc would build and
// each writing its files under projectRoot/<PBDir>, where
// `paths=source_relative` places `a/b.proto` at `a/b.pb.go`. A set
// compiled with the plugins disabled writes nothing.
func RunPlugins(set *Set, projectRoot string) error {
	if set == nil || !set.Options.PBEnabled() {
		return nil
	}
	out := filepath.Join(projectRoot, filepath.FromSlash(strings.TrimPrefix(set.Options.PBDir, "./")))
	for _, p := range set.Options.plugins() {
		argv, err := resolvePlugin(projectRoot, p)
		if err != nil {
			return err
		}
		resp, err := runPlugin(projectRoot, argv, set.Request)
		if err != nil {
			return fmt.Errorf("%s: %w", p.Name, err)
		}
		if err := writeResponse(out, resp); err != nil {
			return fmt.Errorf("%s: %w", p.Name, err)
		}
	}
	return nil
}

// resolvePlugin finds the executable for p. A command named in the
// manifest is run as given (a bare name is looked up on PATH). Otherwise
// the plugin is the one go.mod pins as a tool - `go tool -n` builds it
// and prints where - so the plugin version is the project's protobuf
// version, on every machine, and a plugin on PATH is never picked up
// unasked.
func resolvePlugin(projectRoot string, p Plugin) ([]string, error) {
	if p.Command != "" {
		if strings.ContainsAny(p.Command, `/\`) {
			return []string{p.Command}, nil
		}
		path, err := exec.LookPath(p.Command)
		if err != nil {
			return nil, fmt.Errorf("proto.plugins names %q for %s: %w", p.Command, p.Name, err)
		}
		return []string{path}, nil
	}
	probe := exec.Command("go", "tool", "-n", p.Name)
	probe.Dir = projectRoot
	var stdout, stderr bytes.Buffer
	probe.Stdout, probe.Stderr = &stdout, &stderr
	if err := probe.Run(); err != nil {
		return nil, fmt.Errorf("%s is not a tool of the go.mod at %s (%s)\n"+
			"  pin both plugins once, at the versions the project builds with:\n"+
			"    go get -tool google.golang.org/protobuf/cmd/protoc-gen-go@latest google.golang.org/grpc/cmd/protoc-gen-go-grpc@latest\n"+
			"  or name the command under proto.plugins in craftgo.design.yaml",
			p.Name, projectRoot, strings.TrimSpace(stderr.String()))
	}
	// Only stdout is the path: a cold module cache puts `go: downloading`
	// lines on stderr first.
	return []string{toolPath(stdout.String())}, nil
}

// toolPath is the executable `go tool -n` printed: its last non-empty
// line, trimmed.
func toolPath(stdout string) string {
	lines := strings.Split(strings.TrimSpace(stdout), "\n")
	return strings.TrimSpace(lines[len(lines)-1])
}

// runPlugin feeds req to the plugin on stdin and decodes its response.
func runPlugin(projectRoot string, argv []string, req *pluginpb.CodeGeneratorRequest) (*pluginpb.CodeGeneratorResponse, error) {
	in, err := proto.Marshal(req)
	if err != nil {
		return nil, err
	}
	cmd := exec.Command(argv[0], argv[1:]...)
	cmd.Dir = projectRoot
	cmd.Stdin = bytes.NewReader(in)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("%s: %w\n%s", argv[0], err, strings.TrimSpace(stderr.String()))
	}
	resp := &pluginpb.CodeGeneratorResponse{}
	if err := proto.Unmarshal(stdout.Bytes(), resp); err != nil {
		return nil, fmt.Errorf("%s answered something other than a CodeGeneratorResponse: %w", argv[0], err)
	}
	if resp.Error != nil {
		return nil, errors.New(resp.GetError())
	}
	return resp, nil
}

// writeResponse writes every file of resp under out. A name is relative
// and slash-separated by the plugin protocol; one that escapes out, or
// an insertion into another plugin's file, is refused.
func writeResponse(out string, resp *pluginpb.CodeGeneratorResponse) error {
	for _, f := range resp.GetFile() {
		name := f.GetName()
		if name == "" || strings.HasPrefix(name, "/") || strings.Contains(name, "..") {
			return fmt.Errorf("refusing to write %q outside %s", name, out)
		}
		if f.GetInsertionPoint() != "" {
			return fmt.Errorf("%s: insertion points are not supported", name)
		}
		path := filepath.Join(out, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, []byte(f.GetContent()), 0o644); err != nil {
			return err
		}
	}
	return nil
}
